 private Ui u; private Store store; private JSONObject plan,catalog,legacy; private Onboarding onboarding; private final Map<String,JSONObject> planCache=new HashMap<>();
 private LinearLayout content,root; private ScrollView scroll;
 private int tab=0; private LocalDate date=LocalDate.now(),lastToday=LocalDate.now();
 private final Locale pt=new Locale("pt","BR");
