 private static final int EXPORT=101,IMPORT=102;
 @Override public void onCreate(Bundle saved){
  super.onCreate(saved);u=new Ui(this);store=new Store(this);
  try(InputStream in=getAssets().open("plan.json");InputStream old=getAssets().open("legacy-plan.json")){catalog=new JSONObject(read(in,1000000));legacy=new JSONObject(read(old,1000000));}
  catch(Exception e){error(e);return;}
  if(saved!=null){tab=saved.getInt("tab",0);String d=saved.getString("date");if(Core.checkDate(d))date=LocalDate.parse(d);}
  if(!store.state().optBoolean("onboarded")||saved!=null&&saved.containsKey("onboarding"))startOnboarding(saved==null?null:saved.getBundle("onboarding"));else refreshPlan();
 }
 private void startOnboarding(Bundle saved){onboarding=new Onboarding(this,store,catalog,()->{onboarding=null;refreshPlan();},()->{onboarding=null;refreshPlan();},saved);onboarding.show();}
 private void refreshPlan(){try{planCache.clear();if(!store.state().optBoolean("onboarded")){startOnboarding(null);return;}plan=Recommendations.generate(catalog,store.state().getJSONObject("profile"));planCache.put(store.state().getString("activeProfile"),plan);render(false);}catch(Exception e){error(e);}}
 private JSONObject datePlan(){String id=day().optString("profileId");return planById(id);}
 private JSONObject planById(String id){if(id.equals("legacy"))return legacy;if(planCache.containsKey(id))return planCache.get(id);JSONObject snapshot=store.state().optJSONObject("profiles").optJSONObject(id);if(snapshot==null)return plan;try{JSONObject p=Recommendations.generate(catalog,snapshot);planCache.put(id,p);return p;}catch(Exception e){throw new IllegalStateException(e);}}
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putInt("tab",tab);b.putString("date",date.toString());if(onboarding!=null)b.putBundle("onboarding",onboarding.snapshot());}
 @Override protected void onResume(){super.onResume();LocalDate now=LocalDate.now();if(plan!=null&&onboarding==null&&!now.equals(lastToday)){if(date.equals(lastToday))date=now;lastToday=now;render(false);}}
 @Override public void onBackPressed(){if(onboarding!=null){onboarding.back();return;}if(tab!=0){go(0);return;}super.onBackPressed();}
 private String fmt(double n){return String.format(pt,"%.1f",n);}
 private String grams(double n){return n==Math.rint(n)?String.format(pt,"%.0f",n):fmt(n);}
 private int week(){return store.state().optInt("week");}
 private JSONObject day(){return store.day(date.toString());}
 private JSONObject training(){return datePlan().optJSONArray("workouts").optJSONArray(week()).optJSONObject(Core.dayIndex(date));}
 private JSONArray meals(){return datePlan().optJSONArray("days").optJSONObject(Core.dayIndex(date)).optJSONArray("meals");}
 private void put(JSONObject o,String key,Object value){try{o.put(key,value);}catch(JSONException e){throw new IllegalStateException(e);}}
 private void set(JSONArray a,int idx,Object value){try{a.put(idx,value);}catch(JSONException e){throw new IllegalStateException(e);}}
 private void saveDay(JSONObject d){try{store.saveDay(date.toString(),d);}catch(Exception e){error(e);}}
 private void toast(String message){Toast.makeText(this,message,Toast.LENGTH_SHORT).show();}
 private void error(Throwable e){new AlertDialog.Builder(this).setTitle("Não foi possível concluir").setMessage(e.getMessage()==null?"Tente novamente.":e.getMessage()).setPositiveButton("Entendi",null).show();}
 private void go(int target){tab=target;render(false);}
 private String dayName(){return plan.optJSONArray("days").optJSONObject(Core.dayIndex(date)).optString("name");}
