 private double[] totals(JSONObject option){double[] result=new double[5];JSONArray items=option.optJSONArray("items");for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);JSONArray vals=plan.optJSONObject("foods").optJSONObject(item.optString("food")).optJSONArray("values");double[] v=new double[5];for(int j=0;j<5;j++)v[j]=vals.optDouble(j);double[] add=Core.nutrients(v,item.optDouble("g"));for(int j=0;j<5;j++)result[j]+=add[j];}return result;}
 private double[] dailyTotals(){double[] result=new double[5];for(int i=0;i<4;i++){JSONArray options=meals().optJSONObject(i).optJSONArray("options");if(options.length()==0)continue;double[] t=totals(options.optJSONObject(day().optJSONArray("choices").optInt(i)));for(int j=0;j<5;j++)result[j]+=t[j];}return result;}
