 private EditText field(LinearLayout f,String label,String initial,boolean number,int limit){u.add(f,u.text(label,13,Ui.INK,true));EditText input=new EditText(this);input.setText(initial);input.setTextSize(15);input.setInputType(number?InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL:InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES|InputType.TYPE_TEXT_FLAG_MULTI_LINE);if(number){input.setKeyListener(android.text.method.DigitsKeyListener.getInstance("0123456789.,"));input.setRawInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);}input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(limit)});input.setContentDescription(label);u.add(f,input);u.space(f,13);return input;}
