 private void mealHistory(){JSONObject archive=store.state().optJSONObject("archivedDays");ArrayList<String> keys=sorted(archive);StringBuilder text=new StringBuilder("Registros anteriores à edição do perfil. Não são sugestões atuais.\n\n");if(keys.isEmpty())text.append("Nenhuma versão anterior registrada.");for(int i=keys.size()-1;i>=Math.max(0,keys.size()-25);i--){String key=keys.get(i);JSONObject d=archive.optJSONObject(key);JSONObject old=planById(d.optString("profileId"));text.append(key.substring(0,10)).append("\n");JSONArray meals=old.optJSONArray("days").optJSONObject(Core.dayIndex(LocalDate.parse(key.substring(0,10)))).optJSONArray("meals");for(int j=0;j<4;j++){JSONObject m=meals.optJSONObject(j);JSONArray options=m.optJSONArray("options");text.append(d.optJSONArray("meals").optBoolean(j)?"✓ ":"○ ").append(m.optString("label"));if(options.length()>0)text.append(": ").append(options.optJSONObject(d.optJSONArray("choices").optInt(j)).optString("title"));text.append("\n");}text.append("\n");}info("Histórico de refeições",text.toString());}
