 private void sources(){StringBuilder text=new StringBuilder("O aplicativo organiza hábitos e sugestões iniciais conforme o cadastro. Não substitui nutricionista, avaliação médica ou orientação de educação física. Não garante aprovação no TAF.\n\n");JSONArray sources=plan.optJSONArray("sources");for(int i=0;i<sources.length();i++){JSONObject s=sources.optJSONObject(i);text.append(s.optString("title")).append("\n").append(s.optString("detail")).append("\n").append(s.optString("url")).append("\n\n");}text.append("ALIMENTOS DO CARDÁPIO\nTACO por 100 g: kcal; proteína; carboidratos totais; gorduras; fibras.\n\n");JSONObject foods=plan.optJSONObject("foods");for(Iterator<String> i=foods.keys();i.hasNext();){JSONObject food=foods.optJSONObject(i.next());JSONArray n=food.optJSONArray("values");text.append("#").append(food.optInt("taco")).append(" ").append(food.optString("name")).append(": ");for(int j=0;j<5;j++)text.append(j==0?grams(n.optDouble(j))+" kcal":fmt(n.optDouble(j))+" g").append(j==4?"\n":"; ");}info("Fontes e orientações",text.toString());}
 private void exportBackup(){try{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"RumoAoTAF-backup-"+LocalDate.now()+".json");startActivityForResult(i,EXPORT);}catch(Exception e){error(e);}}
 private void importBackup(){try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/json","application/octet-stream","text/plain"});startActivityForResult(i,IMPORT);}catch(Exception e){error(e);}}
 @Override protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(result!=RESULT_OK||intent==null||intent.getData()==null)return;if(request==EXPORT){try(OutputStream out=getContentResolver().openOutputStream(intent.getData(),"wt")){if(out==null)throw new IOException("Arquivo indisponível.");out.write(store.backup().getBytes(StandardCharsets.UTF_8));toast("Backup exportado.");}catch(Exception e){error(e);}}
  else if(request==IMPORT)new Thread(()->{try(InputStream in=getContentResolver().openInputStream(intent.getData())){String raw=read(in,Store.MAX_BACKUP_BYTES);JSONObject candidate=Store.decode(raw);int weights=candidate.getJSONObject("weights").length(),days=candidate.getJSONObject("days").length();runOnUiThread(()->{if(isFinishing()||isDestroyed())return;new AlertDialog.Builder(this).setTitle("Restaurar esta cópia?").setMessage(weights+" pesagens e "+days+" dias de registros.\n\nEsta ação substitui os dados atuais. Exporte uma cópia antes se quiser preservá-los.").setNegativeButton("Cancelar",null).setPositiveButton("Substituir e restaurar",(d,b)->{try{store.restore(raw);store.recovered=false;date=LocalDate.now();refreshPlan();toast("Backup restaurado.");}catch(Exception e){error(e);}}).show();});}catch(Exception e){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())error(e);});}}).start();
 }
 private static String read(InputStream in,int limit)throws IOException{if(in==null)throw new IOException("Não foi possível abrir o arquivo.");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>limit)throw new IOException("Arquivo grande demais para importar.");out.write(buffer,0,n);}return new String(out.toByteArray(),StandardCharsets.UTF_8);}
